// 教案：走方格 DP 推導 —— 為什麼 dp[i][j] = 上面 + 左邊
//
// 這一課只講一件事：這條遞迴式是怎麼推出來的，不是要學生死記公式。
// 核心問題只有一個：走到 (i, j) 這一格，最後一步是從哪裡走過來的？
// 答案只有兩種可能——從上面 (i-1, j) 走下來，或從左邊 (i, j-1) 走過來，
// 這兩種互不重疊，所以把兩邊的走法數加起來，就是這一格的走法數。
//
// 跟走方格判題教案（走方格_AtCoder_Grid1）用同一組地圖，方便對照結果。
// 第 0、1 列每一格都詳細講；第 2 列規則一模一樣，直接跳到結果看答案。
#include <iostream>
#include <string>
#include <vector>

const int MOD = 1000000007;

int main() {
    int h, w;
    std::cin >> h >> w;                          //@ @guide 先讀地圖的大小：h 列、w 行 @tts [next] 先讀進地圖有幾列幾行 @layout sidebar:55 open:container close:locals
    std::vector<std::string> g(h);               //@ @guide 準備 {h} 個字串，一列地圖存一個\n（要等這一行執行完才建好）@tts [next] 準備好放地圖的空間
    for (int i = 0; i < h; ++i) std::cin >> g[i]; //@ @guide 讀第 {i} 列地圖\n. 是通道、# 是牆 @tts [next] 一列一列把地圖讀進來。點是通道，井字號是牆 | @2 [next] 讀第 {i} 列

    std::vector<std::vector<int>> dp(h, std::vector<int>(w, 0)); //@ @guide 這一行要做一張和地圖一樣大的表，每格先填 0\ndp[i][j] ＝ 走到第 i 列第 j 行有幾種走法\n（表要等這一行執行完才長出來）@tts [next] 接著做一張和地圖一樣大的表。每一格記的是「走到這一格有幾種走法」
    dp[0][0] = 1;                                //@ @guide 起點只有一種走法：待在原地，不用走任何一步\n{dp}\n後面每一格都要靠「上面」或「左邊」推出來，只有這一格要手動指定——這是這條遞迴式的起點（base case）@tts [next] 起點填 1。站在起點本身就是一種走法，這是整張表唯一手動填的格子，剩下的每一格都要靠推導算出來
    for (int i = 0; i < h; ++i) {                //@ @guide 外層迴圈選一列：現在填第 {i} 列\n{dp} @tts [next] 先看第 0 列。這一列比較特別，上面沒有格子可以參考 | @2 [next] 換到第 1 列。這次上面真的有東西可以抄了 | @3 [fast @4] 第 2 列用的規則跟前面一模一樣，我們直接跳到算完，看最後的答案 | @4 [next] 第 2 列也用同樣的規則算完了，整張表都填好了 @layout sidebar:55 open:container
        for (int j = 0; j < w; ++j) {            //@ @guide 內層迴圈選一行：第 {i} 列第 {j} 行\n{dp[i][j]:lightblue} @tts [next] 內層迴圈由左往右走完這一列 | @2 [next] 往右一格，現在是第 {j} 行
            if (i == 0 && j == 0) continue;      //@ @guide 起點已經填過 1 了，跳過不要蓋掉 @tts [next] 起點剛才填過了，跳過 | @2 [next] 不是起點，繼續
            if (g[i][j] == '#') {                //@ @guide 先看這一格是不是牆（地圖上的 # 就是牆） @tts [next] 先問這一格是不是牆 | @2 [next] 是牆嗎
                dp[i][j] = 0;                    //@ @guide 這一格是牆，走不進來\n{dp[i][j]:pink}\n不管上面或左邊算出多少，牆一律直接填 0——這格不會是任何路徑的最後一步 @tts [next] 這一格是牆，走不進來，所以走法直接算 0，不管上面或左邊有多少種走法都不算數 | @2 [next] 又是牆，一樣填 0
                continue;                        //@ @guide 這一格處理完了 @tts [next] 這一格處理完了 | @2 [next] 換下一格
            }
            int up = (i > 0) ? dp[i - 1][j] : 0; //@ @guide 從上面來的走法有幾種？\n{dp[i - 1][j]:orange}\n（在第 0 列就沒有上面，直接算 0；其餘每一列，上面就是 dp[i-1][j] 那一格已經算好的走法數） @tts [next] 能走到這一格的路，要先看兩個方向的來源。先看上面：這一格在第 0 列，上面沒有格子，上面來源直接算 0 | @2 [next] 還是第 0 列，上面一樣沒有格子 | @3 [next] 現在換到第 1 列，上面真的有格子了：dp[i 減 1][j]，直接把上面那一格的走法數抄過來 | @4 [next] 上面是 dp[i 減 1][j]，值是 {dp[i - 1][j]}
            int left = (j > 0) ? dp[i][j - 1] : 0; //@ @guide 再看左邊來的走法有幾種？\n{dp[i][j - 1]:lime}\n（在最左邊（第 0 行）沒有左邊，直接算 0；其餘每一行，左邊就是 dp[i][j-1] 那一格已經算好的走法數） @tts [next] 再看左邊：這一格不是最左邊，左邊有格子，把左邊那一格的走法數抄過來 | @2 [next] 左邊是 dp[i][j 減 1]，值是 {dp[i][j - 1]} | @3 [next] 這一格在最左邊，左邊沒有格子，左邊來源直接算 0——跟第 0 列「上面沒有格子」是同一種邊界 | @4 [next] 左邊是 dp[i][j 減 1]，值是 {dp[i][j - 1]}
            dp[i][j] = (up + left) % MOD;        //@ @guide 把兩個來源加起來，就是這一格的走法數\n{dp[i - 1][j]:orange} 上面\n{dp[i][j - 1]:lime} 左邊\n{dp[i][j]:lightblue} 這一格\n為什麼用加的：走到這一格的路，最後一步只有兩種可能——從上面走下來，或從左邊走過來，兩種路徑不會重複，所以把兩邊的走法數直接加起來 @tts [next] 為什麼是用加的：走到這一格的最後一步，只有從上面下來、或從左邊過來這兩種可能，兩種不會重複，所以把兩邊的走法數加起來，就是這一格的答案：上面 {up} 加左邊 {left} | @2 [next] 上面 {up} 加左邊 {left}，寫進這一格
        }
    }
    std::cout << dp[h - 1][w - 1] << "\n";       //@ @guide 整張表填完了：{dp}\n答案在右下角\n{dp[h - 1][w - 1]:orange} @tts [next] 表填完了，答案就是右下角那一格：每一格都是上面加左邊推出來的，牆是唯一的例外，直接填 0
    return 0;                                    //@ @tts [continue] 教案播放完畢
}
